reclamosEps = FileAttachment("data/processed/citas_reclamos_eps.csv").csv()
  .then(filas =&gt; filas.map(d =&gt; ({...d, afiliados: +d.afiliados, negacion: +d.negacion, demora: +d.demora, total: +d.total, total_10k: +d.total_10k, negacion_10k: +d.negacion_10k, pct_negacion: +d.pct_negacion})))

